"""Pack data/ into src/web_assets.h so a single firmware flash serves the UI."""

Import("env")  # type: ignore[name-defined]  # noqa: F821 — PlatformIO SCons

from pathlib import Path

PROJECT = Path(env["PROJECT_DIR"]).resolve()  # type: ignore[name-defined]
DATA = PROJECT / "data"
OUT = PROJECT / "src" / "web_assets.h"
DELIM = "diwali"


def c_string_name(filename: str) -> str:
    stem = filename.replace(".", "_").replace("-", "_")
    return f"ASSET_{stem.upper()}"


parts = [
    "// Auto-generated by scripts/embed_assets.py — do not edit.",
    "#pragma once",
    "",
]

files = sorted(p for p in DATA.iterdir() if p.is_file())
if not files:
    print(f"ERROR: no assets in {DATA}")
    env.Exit(1)  # type: ignore[name-defined]

for path in files:
    text = path.read_text(encoding="utf-8")
    if f"){DELIM}\"" in text or f"){DELIM}" in text:
        print(f"ERROR: {path.name} contains raw-string delimiter ){DELIM}")
        env.Exit(1)  # type: ignore[name-defined]
    name = c_string_name(path.name)
    parts.append(f"static const char {name}[] = R\"{DELIM}({text}){DELIM}\";")
    parts.append("")

OUT.write_text("\n".join(parts), encoding="utf-8")
print(f"Embedded {len(files)} asset(s) → {OUT.relative_to(PROJECT)}")
